contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We observe effects of withdraw(amount) on this contract when invoked on c.
    // Parameters: amount to attempt to withdraw.
    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record balances observable before the call
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;

        // Try withdraw; capture whether it reverted
        bool didRevert;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        // record balances after the call
        uint256 contractBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;

        // The rule: if withdraw succeeded then (1) the recorded mapping balance for this caller as
        // observable via ability to withdraw again, decreases by exactly amount — we can't read mapping,
        // but we can observe that attempting to withdraw more than remaining should revert.
        // We instead assert two observable consequences:
        //  - If withdraw succeeded then contract's balance decreased by at least 0 (monotonic) and
        //    this contract's Ether balance did not increase by more than amount.
        //  - Also, if withdraw succeeded then either contract balance decreased by at least amount or
        //    some other transfer to this contract occurred; combined we assert selfBalAfter <= selfBalBefore + amount
        // These observable constraints hold for correct withdraw implementation.

        assert(
            didRevert
            ? (contractBalAfter == contractBalBefore && selfBalAfter == selfBalBefore)
            : (selfBalAfter <= selfBalBefore + amount)
        );
    }

    receive() external payable {}
}

