// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        uint256 contractBalBefore = address(c).balance;
        uint256 selfBalBefore = address(this).balance;
        bool didRevert;
        try c.withdraw(amount) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 contractBalAfter = address(c).balance;
        uint256 selfBalAfter = address(this).balance;
        assertTrue(didRevert
            ? (contractBalAfter == contractBalBefore && selfBalAfter == selfBalBefore)
            : (selfBalAfter <= selfBalBefore + amount));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
